import{_ as a,c as n,o as t,ae as i}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Datenschutz und deine Daten","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/privacy.md","filePath":"de/guide/privacy.md","lastUpdated":1795170900000}'),r={name:"de/guide/privacy.md"};function d(s,e,u,l,o,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="datenschutz-und-deine-daten" tabindex="-1">Datenschutz und deine Daten <a class="header-anchor" href="#datenschutz-und-deine-daten" aria-label="Permalink to &quot;Datenschutz und deine Daten&quot;">​</a></h1><p>Was auf deinem Mac bleibt und wann das Netz nötig ist.</p><h2 id="lokal-gespeichert" tabindex="-1">Lokal gespeichert <a class="header-anchor" href="#lokal-gespeichert" aria-label="Permalink to &quot;Lokal gespeichert&quot;">​</a></h2><p>Verlauf, Lesezeichen, offene Tabs, Downloads und Cookies liegen auf deinem Mac. Es gibt kein Konto und keine Cloud-Synchronisierung. Ein privates Fenster (⌘⇧N) hinterlässt keine Spuren in Verlauf und Sitzung.</p><h2 id="wann-das-netz-genutzt-wird" tabindex="-1">Wann das Netz genutzt wird <a class="header-anchor" href="#wann-das-netz-genutzt-wird" aria-label="Permalink to &quot;Wann das Netz genutzt wird&quot;">​</a></h2><ul><li>Natürlich beim Laden der Seiten, die du aufrufst.</li><li>Beim Aktualisieren eines aktiven Werbeblocker-Abonnements. Schlägt das fehl, gelten die gespeicherten Regeln weiter.</li><li>Beim Herunterladen eines Skripts oder einer Datei, die du angefordert hast.</li></ul><h2 id="deine-berechtigungen" tabindex="-1">Deine Berechtigungen <a class="header-anchor" href="#deine-berechtigungen" aria-label="Permalink to &quot;Deine Berechtigungen&quot;">​</a></h2><p>Kamera und Mikrofon werden pro Seite gemerkt. Standort und Benachrichtigungen verwaltet macOS selbst. Pop-ups sind auf erlaubte Seiten beschränkt.</p><h2 id="dateien-auf-der-platte" tabindex="-1">Dateien auf der Platte <a class="header-anchor" href="#dateien-auf-der-platte" aria-label="Permalink to &quot;Dateien auf der Platte&quot;">​</a></h2><p>Persim liest nur Dateien, die du im Systemdialog auswählst oder ausdrücklich freigibst. Freigaben kannst du in den Einstellungen prüfen und widerrufen.</p><h2 id="kontakt" tabindex="-1">Kontakt <a class="header-anchor" href="#kontakt" aria-label="Permalink to &quot;Kontakt&quot;">​</a></h2><p>Fragen zum Datenschutz: <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>.</p>',12)])])}const g=a(r,[["render",d]]);export{p as __pageData,g as default};
